/* ==========================================================================
   SupaEdit - Zero-Dependency Client-Side ZIP Generator
   ========================================================================== */

class SimpleZip {
  constructor() {
    this.files = [];
  }

  addFile(filename, dataUint8Array) {
    this.files.push({ name: filename, data: dataUint8Array });
  }

  // Generate standard uncompressed Store ZIP blob
  generateBlob() {
    const parts = [];
    const cdEntries = [];
    let offset = 0;

    for (const f of this.files) {
      const nameBytes = new TextEncoder().encode(f.name);
      const data = f.data;
      const crc = this.crc32(data);

      const header = new Uint8Array(30 + nameBytes.length);
      const view = new DataView(header.buffer);

      view.setUint32(0, 0x04034b50, true); // Local header signature
      view.setUint16(4, 20, true);         // Version needed
      view.setUint16(6, 0, true);          // General flag
      view.setUint16(8, 0, true);          // Compression method (0 = store)
      view.setUint16(10, 0, true);         // Mod time
      view.setUint16(12, 0, true);         // Mod date
      view.setUint32(14, crc, true);       // CRC32
      view.setUint32(18, data.length, true); // Compressed size
      view.setUint32(22, data.length, true); // Uncompressed size
      view.setUint16(26, nameBytes.length, true); // Filename length
      view.setUint16(28, 0, true);         // Extra field length
      header.set(nameBytes, 30);

      parts.push(header);
      parts.push(data);

      // Save Central Directory Entry
      const cdHeader = new Uint8Array(46 + nameBytes.length);
      const cdView = new DataView(cdHeader.buffer);
      cdView.setUint32(0, 0x02014b50, true); // CD signature
      cdView.setUint16(4, 20, true);
      cdView.setUint16(6, 20, true);
      cdView.setUint16(8, 0, true);
      cdView.setUint16(10, 0, true);
      cdView.setUint32(16, crc, true);
      cdView.setUint32(20, data.length, true);
      cdView.setUint32(24, data.length, true);
      cdView.setUint16(28, nameBytes.length, true);
      cdView.setUint32(42, offset, true); // Local header offset
      cdHeader.set(nameBytes, 46);

      cdEntries.push(cdHeader);
      offset += header.length + data.length;
    }

    const cdOffset = offset;
    let cdSize = 0;
    for (const cd of cdEntries) {
      parts.push(cd);
      cdSize += cd.length;
    }

    // End of Central Directory Record
    const eocd = new Uint8Array(22);
    const eocdView = new DataView(eocd.buffer);
    eocdView.setUint32(0, 0x06054b50, true);
    eocdView.setUint16(8, this.files.length, true);
    eocdView.setUint16(10, this.files.length, true);
    eocdView.setUint32(12, cdSize, true);
    eocdView.setUint32(16, cdOffset, true);
    parts.push(eocd);

    return new Blob(parts, { type: 'application/zip' });
  }

  crc32(r) {
    let c = -1;
    for (let i = 0; i < r.length; i++) {
      c = (c >>> 8) ^ SimpleZip.crcTable[(c ^ r[i]) & 0xff];
    }
    return (c ^ -1) >>> 0;
  }
}

SimpleZip.crcTable = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 8) : c >>> 8;
    }
    table[n] = c;
  }
  return table;
})();

window.SimpleZip = SimpleZip;
